export interface ConnectorConfig {
  /** Airtable Personal Access Token or API Key for fetching webhook payloads. */
  airtableApiKey: string
  /** Discord webhook URL (format: https://discord.com/api/webhooks/{id}/{token}). */
  discordWebhookUrl: string
  /** Optional fetch implementation for testing. */
  fetch?: typeof fetch
}

export interface AirtableWebhookNotification {
  baseId: string
  tableId: string
  webhookId: string
  timestamp: number
  payloadId: string
}

export interface AirtableRecordPayload {
  id: string
  fields: Record<string, unknown>
  createdTime: string
}

export interface AirtablePayloadsResponse {
  payloads: Array<{ payload: AirtableRecordPayload }>
}

export interface DiscordWebhookPayload {
  content?: string
  embeds?: Array<{
    fields?: Array<{ name: string; value: string }>
    timestamp?: string
  }>
}

export interface HandleResult {
  discordMessageId: string
  discordChannelId: string
  processedRecords: number
}

async function fetchWithAuth(
  url: string,
  options: RequestInit & { headers?: Record<string, string> },
  fetchImpl: typeof fetch,
): Promise<Response> {
  const headers = new Headers(options.headers)
  return fetchImpl(url, { ...options, headers })
}

export async function handle(
  payload: AirtableWebhookNotification,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.baseId) throw new Error('Missing required field: baseId')
  if (!payload.webhookId) throw new Error('Missing required field: webhookId')
  if (!config.airtableApiKey) throw new Error('Missing config: airtableApiKey')
  if (!config.discordWebhookUrl) throw new Error('Missing config: discordWebhookUrl')

  const payloadsUrl = `https://api.airtable.com/v0/bases/${payload.baseId}/webhooks/${payload.webhookId}/payloads`

  const payloadsResponse = await fetchWithAuth(
    payloadsUrl,
    {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${config.airtableApiKey}`,
        'Content-Type': 'application/json',
      },
    },
    fetchImpl,
  )

  if (!payloadsResponse.ok) {
    throw new Error(
      `Airtable payloads fetch failed: ${payloadsResponse.status} ${payloadsResponse.statusText} at ${payloadsUrl}`,
    )
  }

  const payloadsData = (await payloadsResponse.json()) as AirtablePayloadsResponse

  if (!payloadsData.payloads || payloadsData.payloads.length === 0) {
    return { discordMessageId: '', discordChannelId: '', processedRecords: 0 }
  }

  const records = payloadsData.payloads.map((p) => p.payload)

  const embeds = records.map((record) => {
    const fields = Object.entries(record.fields).map(([name, value]) => ({
      name,
      value: String(value),
    }))

    return {
      fields,
      timestamp: record.createdTime,
    }
  })

  const content = records.map((r) => r.id).join(', ')

  const discordPayload: DiscordWebhookPayload = {
    content: content.slice(0, 2000),
    embeds: embeds.slice(0, 10),
  }

  const discordResponse = await fetchWithAuth(
    config.discordWebhookUrl,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(discordPayload),
    },
    fetchImpl,
  )

  if (!discordResponse.ok) {
    throw new Error(
      `Discord webhook send failed: ${discordResponse.status} ${discordResponse.statusText} at ${config.discordWebhookUrl}`,
    )
  }

  const discordData = (discordResponse.status === 204
    ? { id: '', channel_id: '' }
    : (await discordResponse.json())) as { id: string; channel_id: string }

  return {
    discordMessageId: discordData.id,
    discordChannelId: discordData.channel_id,
    processedRecords: records.length,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, AirtableWebhookNotification } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      airtableApiKey: 'test-airtable-key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookNotification, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.processedRecords).toBeGreaterThanOrEqual(0)
  })
})

describe('handle', () => {
  it('throws when baseId is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, baseId: '' } as AirtableWebhookNotification
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: baseId')
  })

  it('throws when webhookId is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, webhookId: '' } as AirtableWebhookNotification
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: webhookId')
  })

  it('throws when airtableApiKey is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtableApiKey: '',
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }
    await expect(handle(SOURCE_EXAMPLE as unknown as AirtableWebhookNotification, config)).rejects.toThrow(
      'Missing config: airtableApiKey',
    )
  })

  it('throws when discordWebhookUrl is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      discordWebhookUrl: '',
      fetch,
    }
    await expect(handle(SOURCE_EXAMPLE as unknown as AirtableWebhookNotification, config)).rejects.toThrow(
      'Missing config: discordWebhookUrl',
    )
  })

  it('fetches payloads from Airtable and sends to Discord on happy path', async () => {
    const airtablePayloadsResponse = {
      payloads: [
        {
          payload: {
            id: 'recABC123',
            fields: { Name: 'Test Record', Status: 'Active', Count: 42 },
            createdTime: '2023-04-10T12:34:56.000Z',
          },
        },
        {
          payload: {
            id: 'recDEF456',
            fields: { Name: 'Another Record', Status: 'Pending' },
            createdTime: '2023-04-10T13:00:00.000Z',
          },
        },
      ],
    }

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/payloads')) {
        return jsonResponse(airtablePayloadsResponse, 200)
      }
      if (req.url.includes('discord.com/api/webhooks')) {
        return jsonResponse({ id: 'msg123', channel_id: 'chan456' }, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      airtableApiKey: 'patTEST123',
      discordWebhookUrl: 'https://discord.com/api/webhooks/wh123/token456',
      fetch,
    }

    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookNotification, config)

    expect(calls.length).toBe(2)
    expect(calls[0].method).toBe('GET')
    expect(calls[0].url).toContain('/bases/appXXXXXXXXXXXXXX/webhooks/whXXXXXXXXXXXXXX/payloads')
    expect(calls[0].headers.get('authorization')).toBe('Bearer patTEST123')

    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toBe('https://discord.com/api/webhooks/wh123/token456')
    expect(calls[1].json).toEqual({
      content: 'recABC123, recDEF456',
      embeds: [
        {
          fields: [
            { name: 'Name', value: 'Test Record' },
            { name: 'Status', value: 'Active' },
            { name: 'Count', value: '42' },
          ],
          timestamp: '2023-04-10T12:34:56.000Z',
        },
        {
          fields: [
            { name: 'Name', value: 'Another Record' },
            { name: 'Status', value: 'Pending' },
          ],
          timestamp: '2023-04-10T13:00:00.000Z',
        },
      ],
    })

    expect(result).toEqual({
      discordMessageId: 'msg123',
      discordChannelId: 'chan456',
      processedRecords: 2,
    })
  })

  it('handles empty payloads array from Airtable', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/payloads')) {
        return jsonResponse({ payloads: [] }, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }

    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookNotification, config)

    expect(calls.length).toBe(1)
    expect(result).toEqual({
      discordMessageId: '',
      discordChannelId: '',
      processedRecords: 0,
    })
  })

  it('throws on non-2xx Airtable response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/payloads')) {
        return jsonResponse({ error: 'Unauthorized' }, 401)
      }
      return jsonResponse({}, 200)
    })

    const config: ConnectorConfig = {
      airtableApiKey: 'bad-key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }

    await expect(handle(SOURCE_EXAMPLE as unknown as AirtableWebhookNotification, config)).rejects.toThrow(
      'Airtable payloads fetch failed: 401 Unauthorized',
    )
  })

  it('throws on non-2xx Discord response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/payloads')) {
        return jsonResponse({
          payloads: [{ payload: { id: 'rec1', fields: { A: '1' }, createdTime: '2023-01-01T00:00:00.000Z' } }],
        }, 200)
      }
      if (req.url.includes('discord.com/api/webhooks')) {
        return jsonResponse({ error: 'Invalid Webhook Token' }, 401)
      }
      return jsonResponse({}, 404)
    })

    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }

    await expect(handle(SOURCE_EXAMPLE as unknown as AirtableWebhookNotification, config)).rejects.toThrow(
      'Discord webhook send failed: 401 Unauthorized',
    )
  })

  it('handles Discord 204 No Content response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/payloads')) {
        return jsonResponse({
          payloads: [{ payload: { id: 'rec1', fields: { A: '1' }, createdTime: '2023-01-01T00:00:00.000Z' } }],
        }, 200)
      }
      if (req.url.includes('discord.com/api/webhooks')) {
        return jsonResponse(null, 204)
      }
      return jsonResponse({}, 404)
    })

    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }

    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookNotification, config)

    expect(calls.length).toBe(2)
    expect(result).toEqual({
      discordMessageId: '',
      discordChannelId: '',
      processedRecords: 1,
    })
  })

  it('truncates content to 2000 chars and embeds to 10', async () => {
    const manyRecords = Array.from({ length: 15 }, (_, i) => ({
      payload: {
        id: `rec${i}`,
        fields: { Field: `Value ${i}` },
        createdTime: '2023-01-01T00:00:00.000Z',
      },
    }))

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/payloads')) {
        return jsonResponse({ payloads: manyRecords }, 200)
      }
      if (req.url.includes('discord.com/api/webhooks')) {
        return jsonResponse({ id: 'msg1', channel_id: 'chan1' }, 200)
      }
      return jsonResponse({}, 404)
    })

    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }

    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookNotification, config)

    expect(result.processedRecords).toBe(15)
    const discordCall = calls[1]
    expect(discordCall.json).toBeDefined()
    const payload = discordCall.json as { content: string; embeds: unknown[] }
    expect(payload.content.length).toBeLessThanOrEqual(2000)
    expect(payload.embeds.length).toBe(10)
  })
})

